using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing AutomationFramework.Core.Utilities;\nusing Serilog;\nusing Newtonsoft.Json;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetstoreSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetApiHelper _petApiHelper;\n        private RestResponse _response;\n\n        public PetstoreSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petApiHelper = new PetApiHelper();\n        }\n\n        [Given(\"the API endpoint is \\\"(.*)\\\"\")]\n        public void GivenTheApiEndpointIs(string endpoint)\n        {\n            _scenarioContext[\"Endpoint\"] = endpoint;\n            Log.Information(\"Endpoint set to: {Endpoint}\", endpoint);\n        }\n\n        [When(\"I send a POST request with the following payload\")]\n        public void WhenISendAPostRequestWithTheFollowingPayload(Table table)\n        {\n            var payload = new {\n                id = table.Rows[0][\"id\"],\n                name = table.Rows[0][\"name\"],\n                status = table.Rows[0][\"status\"]\n            };\n            _response = _petApiHelper.SendPostRequest(_scenarioContext[\"Endpoint\"].ToString(), payload);\n            Log.Information(\"POST request sent to {Endpoint} with payload: {Payload}\", _scenarioContext[\"Endpoint\"], JsonConvert.SerializeObject(payload));\n        }\n\n        [When(\"I send a GET request\")]\n        public void WhenISendAGetRequest()\n        {\n            _response = _petApiHelper.SendGetRequest(_scenarioContext[\"Endpoint\"].ToString());\n            Log.Information(\"GET request sent to {Endpoint}\", _scenarioContext[\"Endpoint\"]);\n        }\n\n        [When(\"I send a PUT request with the following payload\")]\n        public void WhenISendAPutRequestWithTheFollowingPayload(Table table)\n        {\n            var payload = new {\n                id = table.Rows[0][\"id\"],\n                name = table.Rows[0][\"name\"],\n                status = table.Rows[0][\"status\"]\n            };\n            _response = _petApiHelper.SendPutRequest(_scenarioContext[\"Endpoint\"].ToString(), payload);\n            Log.Information(\"PUT request sent to {Endpoint} with payload: {Payload}\", _scenarioContext[\"Endpoint\"], JsonConvert.SerializeObject(payload));\n        }\